sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try { //MSSTRUSTES-43
        var payload = '';
        var method = '';
        var category = current.category_aml.toString();
        var subcategory = current.sub_category.toString();
        var scheme = current.scheme_code.toLowerCase();
        var hkIdNum = current.identification_hkid_card_auth_pers_1.toString();
		hkIdNum = hkIdNum.replace(/[()]/g, ""); //MSStrustes-266

        switch (subcategory) {
            case 'er':
                payload = {
                    "schemeCode": current.scheme_code.toString(),
                    "employerAccountType": current.employer_account_type.toString(),
                    "eMPFId": current.er_id.toString()
                };

                method = (category === 'new_enrollment') ? 'query-er-form-info' :
                    (category === 'periodic_review_query') ? 'query-er-periodic-review-form-info' : ''; //MSSTRUSTES-185

                break;
            case 'ee':
                payload = {
                    "schemeCode": current.scheme_code.toString(),
                    "accountType": current.member_account_type_1_ee.toString(),
                    "passport": current.identification_passportno_auth_pers_1.toString(),
                    "hKIdNumber": hkIdNum.slice(0, -1), ////MSSTRUSTES-185 
                    "hKIdCheckDigit": hkIdNum.slice(-1) ////MSSTRUSTES-185
                };

                method = (category === 'new_enrollment') ? 'query-ee-form-info' :
                    (category === 'periodic_review_query') ? 'query-ee-periodic-review-form-info' : ''; //MSSTRUSTES-185

                break;
            default:
                break;
        }

        new x_hsb11_mss_trus_0.MSSTrusteesCallUtils().updateOutboundrecord(current.sys_id, payload, method, scheme, subcategory);
    } catch (error) {
        gs.info('Error in Business Rule - GetAMLKYCCaseDetail' + error.message);
    }
})(current, previous);
